async function render(){clearTimeout(broadcastPollTimer);clearTimeout(chatPollTimer);if(state.page==='home'){renderAnnouncement();$("#app").innerHTML=home();loadStats();return}$("#app").innerHTML='<section class="panel pagePanel"><div class="loading">جاري التحميل...</div></section>';try{$("#app").innerHTML=await buildPage(state.page);bindPage(state.page);if(state.page==="owner")pollBroadcastJobs()}catch(e){$("#app").innerHTML='<section class="panel pagePanel"><h1>تعذر التحميل</h1><p class="muted">'+esc(e.message)+'</p></section>'}}
function bindPage(p){if(p==='members'){$('#memberSearch')?.addEventListener('input',async e=>{try{const q=e.target.value.trim();const d=await api(q?'/api/public/members?q='+encodeURIComponent(q):'/api/public/members?limit=100&offset=0');state.memberOffset=d.members.length;state.memberTotal=d.total||0;const grid=$('#memberGrid');if(grid)grid.innerHTML=d.members.map(m=>'<button class="memberCard" data-member="'+esc(m.id)+'"><img src="'+esc(m.avatar)+'"><b>'+esc(m.name)+'</b><small>@'+esc(m.username)+'</small></button>').join('')||'<div class="empty">ما لقينا أعضاء بهذا الاسم.</div>';const count=$('#memberCount');if(count)count.textContent='عرض '+d.members.length+' من '+state.memberTotal.toLocaleString('ar-SA')+' عضو';const more=$('#loadMoreMembers');if(more)more.hidden=!d.hasMore||!!q;}catch(err){toast(err.message)}})}if(p==='games'){gameSocketConnect();loadGameSessions();}if(p==='cinema'){const botSelect=$('#cinemaBotSelect'),roomSelect=$('#cinemaRoomSelect');const loadRooms=async()=>{if(!botSelect||!roomSelect)return;roomSelect.innerHTML='<option value="">جاري تحميل الرومات…</option>';if(!botSelect.value){roomSelect.innerHTML='<option value="">اختر البوت أولًا</option>';return}try{const d=await api('/api/community/cinema/discord-rooms?bot_id='+encodeURIComponent(botSelect.value));roomSelect.innerHTML='<option value="">اختر الروم</option>'+(d.rooms||[]).map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+(r.type===2?' · صوتي':r.type===13?' · Stage':r.type===5?' · إعلانات':' · كتابي')+'</option>').join('')}catch(err){roomSelect.innerHTML='<option value="">تعذر تحميل الرومات</option>';toast(err.message)}};botSelect?.addEventListener('change',loadRooms);loadRooms();}}
function go(page){if(!page)return;if(protectedPages.has(page)&&!state.user){openLogin();return}state.page=page;renderHeader();render();closeMenu();window.scrollTo(0,0)}
function openLogin(){const auth='<div class="dialog"><div class="dialogHead"><h2>مرحباً بك في ملاذ</h2><button class="close" type="button" data-close>×</button></div><div class="auth-tabs"><button class="auth-tab active" type="button" data-auth-tab="login">تسجيل الدخول</button><button class="auth-tab" type="button" data-auth-tab="register">إنشاء حساب</button></div><form id="loginForm" class="auth-form active"><div class="field"><label>اسم المستخدم</label><input name="username" autocomplete="username" required></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn primary" type="submit" style="width:100%">دخول</button></form><form id="registerForm" class="auth-form"><div class="field"><label>اسم المستخدم في الموقع</label><input name="username" minlength="2" maxlength="24" autocomplete="username" required></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></div><div class="field"><label>حسابك في Discord</label><div class="user-picker"><input data-user-picker-input autocomplete="off" placeholder="اكتب اسمك واختر حسابك من الاقتراحات" required><div class="user-suggestions" data-user-suggestions></div><input type="hidden" name="discord_id" data-user-picker-id></div><small class="form-help">اختر حسابك من سيرفر MLD ثم اضغط إرسال كود التحقق.</small></div><button class="btn" type="button" data-send-verification style="width:100%">إرسال كود التحقق إلى Discord</button><div class="field"><label>كود التحقق المرسل لك بالخاص</label><input name="verification_code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="أدخل الكود المكوّن من 6 أرقام" required></div><button class="btn primary" type="submit" style="width:100%">تأكيد وإنشاء الحساب</button><p class="form-help">الكود صالح لمدة 10 دقائق. بعد التأكيد ينشأ حسابك مباشرة، ولا تحتاج أمرًا في البوت أو تذكرة تسجيل.</p></form></div>';$("#modal").innerHTML=auth;$("#modal").classList.add("open");$("#shade")?.classList.add("open")}
function logout(){state.token="";state.user=null;save();state.page="home";renderHeader();render();toast("تم تسجيل الخروج")}
async function consumeLoginTicket(){const match=window.location.hash.match(/(?:^#|&)login_ticket=([^&]+)/);if(!match)return;let ticket;try{ticket=decodeURIComponent(match[1])}catch{return}history.replaceState(null,'',window.location.pathname+window.location.search);try{const d=await api('/api/auth/bot/exchange-ticket',{method:'POST',body:JSON.stringify({ticket})});state.token=d.token;state.user=d.user;save();renderHeader();render();toast('تم تسجيل الدخول عبر بوت MLD')}catch(error){toast(error.message||'تعذر استهلاك رابط الدخول')}}
